import heapq

def applyOrder(config):
    ident = set("abcdefghijklmnopqrstuvwxyz0123456789_")

    def references(expr, addr):
        start = 0
        while True:
            i = expr.find(addr, start)
            if i == -1:
                return False
            before = expr[i - 1] if i > 0 else ""
            after = expr[i + len(addr)] if i + len(addr) < len(expr) else ""
            if not (before in ident or before == ".") and after not in ident:
                return True
            start = i + 1

    deps = {a: set() for a in config}
    for a, exprs in config.items():
        for b in config:
            if b != a and any(references(e, b) for e in exprs):
                deps[a].add(b)

    dependents = {a: [] for a in config}
    remaining = {a: len(d) for a, d in deps.items()}
    for a, d in deps.items():
        for b in d:
            dependents[b].append(a)

    heap = [a for a, n in remaining.items() if n == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        a = heapq.heappop(heap)
        order.append(a)
        for nxt in dependents[a]:
            remaining[nxt] -= 1
            if remaining[nxt] == 0:
                heapq.heappush(heap, nxt)
    return order

tf-destroy-order.solution:
import heapq

def destroyOrder(depends_on, targets):
    dependents = {a: [] for a in depends_on}
    for a, deps in depends_on.items():
        for d in deps:
            dependents[d].append(a)

    doomed = set()
    stack = [t for t in targets]
    while stack:
        node = stack.pop()
        if node in doomed:
            continue
        doomed.add(node)
        stack.extend(dependents[node])

    remaining = {a: len({d for d in depends_on[a] if d in doomed}) for a in doomed}
    heap = [a for a, n in remaining.items() if n == 0]
    heapq.heapify(heap)
    created = []
    while heap:
        a = heapq.heappop(heap)
        created.append(a)
        for nxt in set(dependents[a]):
            if nxt in doomed:
                remaining[nxt] -= 1
                if remaining[nxt] == 0:
                    heapq.heappush(heap, nxt)
    return created[::-1]

tf-cycle-detect.solution:
from collections import deque

def findCycle(depends_on):
    graph = {a: sorted({d for d in deps if d in depends_on}) for a, deps in depends_on.items()}
    reverse = {a: [] for a in graph}
    for a, deps in graph.items():
        for d in deps:
            reverse[d].append(a)

    for s in sorted(graph):
        # dist[x] = fewest arrows needed to get from x to s
        dist = {s: 0}
        queue = deque([s])
        while queue:
            node = queue.popleft()
            for prev in reverse[node]:
                if prev not in dist:
                    dist[prev] = dist[node] + 1
                    queue.append(prev)
        starts = [d for d in graph[s] if d in dist]
        if not starts:
            continue
        best = min(dist[d] for d in starts)
        path = [s]
        node = min(d for d in starts if dist[d] == best)
        while node != s:
            path.append(node)
            node = min(d for d in graph[node] if d in dist and dist[d] == dist[node] - 1)
        path.append(s)
        return "Cycle: " + " -> ".join(path)
    return ""

tf-create-before-destroy.solution:
import heapq

def replacementSteps(resources):
    deps = {r["address"]: sorted(set(r["depends_on"])) for r in resources}
    effective = {r["address"]: bool(r["cbd"]) for r in resources}

    stack = [a for a, v in effective.items() if v]
    while stack:
        node = stack.pop()
        for d in deps[node]:
            if not effective[d]:
                effective[d] = True
                stack.append(d)

    def creation_order(group):
        group = set(group)
        remaining = {a: sum(1 for d in deps[a] if d in group) for a in group}
        dependents = {a: [] for a in group}
        for a in group:
            for d in deps[a]:
                if d in group:
                    dependents[d].append(a)
        heap = [a for a, n in remaining.items() if n == 0]
        heapq.heapify(heap)
        order = []
        while heap:
            a = heapq.heappop(heap)
            order.append(a)
            for nxt in dependents[a]:
                remaining[nxt] -= 1
                if remaining[nxt] == 0:
                    heapq.heappush(heap, nxt)
        return order

    early = [a for a, v in effective.items() if not v]
    late = [a for a, v in effective.items() if v]
    steps = [f"destroy {a}" for a in reversed(creation_order(early))]
    steps += [f"create {a}" for a in creation_order(deps)]
    steps += [f"destroy deposed {a}" for a in reversed(creation_order(late))]
    return steps

tf-count-plan.solution:
def countPlan(resource, old_values, new_values, force_new):
    plan = []
    for i in range(max(len(old_values), len(new_values))):
        if i >= len(old_values):
            action = "create"
        elif i >= len(new_values):
            action = "delete"
        elif old_values[i] == new_values[i]:
            action = "no-op"
        elif force_new:
            action = "replace"
        else:
            action = "update"
        plan.append([f"{resource}[{i}]", action])
    return plan

tf-foreach-plan.solution:
def forEachPlan(resource, old, new, force_new):
    def as_map(collection):
        if isinstance(collection, dict):
            return dict(collection)
        return {item: item for item in collection}

    before, after = as_map(old), as_map(new)
    plan = []
    for key in sorted(set(before) | set(after)):
        if key not in before:
            action = "create"
        elif key not in after:
            action = "delete"
        elif before[key] == after[key]:
            action = "no-op"
        elif force_new:
            action = "replace"
        else:
            action = "update"
        plan.append([f'{resource}["{key}"]', action])
    return plan

tf-for-expression.solution:
def evalFor(collection, spec):
    if isinstance(collection, dict):
        items = sorted(collection.items(), key=lambda kv: kv[0])
    else:
        items = list(enumerate(collection))

    def produce(pair, k, v):
        func, field = pair
        x = k if field == "key" else v
        if func == "upper":
            return x.upper()
        if func == "lower":
            return x.lower()
        if func == "length":
            return len(x)
        return x

    def keep(k, v):
        cond = spec.get("if")
        if not cond:
            return True
        field, op, operand = cond
        x = k if field == "key" else v
        if op == "==":
            return x == operand
        if op == "!=":
            return x != operand
        if op == ">":
            return x > operand
        return x < operand

    if spec["out"] == "list":
        return [produce(spec["value"], k, v) for k, v in items if keep(k, v)]

    grouping = bool(spec.get("group"))
    result = {}
    for k, v in items:
        if not keep(k, v):
            continue
        key = str(produce(spec["key"], k, v))
        value = produce(spec["value"], k, v)
        if grouping:
            result.setdefault(key, []).append(value)
        elif key in result:
            return f'Error: Duplicate object key "{key}"'
        else:
            result[key] = value
    return result

tf-moved-blocks.solution:
def applyMoves(addresses, moves):
    current = set(addresses)
    for src, dst in moves:
        rewritten = {}
        for addr in current:
            if addr == src or addr.startswith(src + "[") or addr.startswith(src + "."):
                rewritten[addr] = dst + addr[len(src):]
        staying = current - set(rewritten)
        clashes = sorted(new for new in rewritten.values() if new in staying)
        if clashes:
            return ["Error: " + clashes[0] + " already exists"]
        current = staying | set(rewritten.values())
    return sorted(current)

tf-parse-address.solution:
def parseAddress(address):
    parts = []                      # [name, key] for each dot-separated step
    i, n = 0, len(address)
    while i < n:
        j = i
        while j < n and address[j] not in ".[":
            j += 1
        name = address[i:j]
        key = None
        if j < n and address[j] == "[":
            if address[j + 1] == '"':
                end = address.index('"', j + 2)
                key = address[j + 2:end]
                j = end + 2         # past the closing quote and the bracket
            else:
                end = address.index("]", j)
                key = int(address[j + 1:end])
                j = end + 1
        parts.append([name, key])
        i = j + 1                   # past the dot

    modules = []
    k = 0
    while parts[k][0] == "module" and len(parts) - k > 2:
        modules.append([parts[k + 1][0], parts[k + 1][1]])
        k += 2
    mode = "managed"
    if parts[k][0] == "data" and len(parts) - k > 2:
        mode = "data"
        k += 1
    return {"modules": modules, "mode": mode, "type": parts[k][0],
            "name": parts[k + 1][0], "key": parts[k + 1][1]}

