def statePaths(backend, workspaces):
    prefix = backend.get("workspace_key_prefix", "env:")
    locking = bool(backend.get("use_lockfile", False))
    result = {}
    for workspace in workspaces:
        if workspace == "default":
            key = backend["key"]
