        result[workspace] = [url, url + ".tflock" if locking else None]
    return result

tf-state-lock.solution:
def lockLog(events):
    holder = None
    lock_id = None
    granted = 0
    out = []
    for event in events:
        kind, arg = event[0], event[1]
        if kind == "lock":
            if holder is None:
                granted += 1
                holder, lock_id = arg, "lock-" + str(granted)
                out.append(lock_id)
            else:
                out.append("Error: state locked by " + holder + " (" + lock_id + ")")
        elif kind == "unlock":
            if holder is None:
                out.append("Error: state is not locked")
            elif holder != arg:
                out.append("Error: lock held by " + holder)
            else:
                holder = lock_id = None
                out.append("unlocked")
        else:
            if holder is None:
                out.append("Error: state is not locked")
            elif arg != lock_id:
                out.append("Error: lock ID " + arg + " does not match")
            else:
                holder = lock_id = None
                out.append("force-unlocked")
    return out

tf-stale-plan.solution:
def replayRuns(start_serial, events):
    serial = start_serial
    plans = {}
    out = []
    for event in events:
        kind = event[0]
        if kind == "plan":
            name, changes = event[1], event[2]
            plans[name] = (serial, changes)
            out.append("Planned " + name + " at serial " + str(serial))
        elif kind == "apply":
            name = event[1]
            if name not in plans:
                out.append("Error: no plan " + name)
                continue
            planned_at, changes = plans[name]
            if planned_at != serial:
                out.append("Error: Saved plan is stale")
                continue
            if changes > 0:
                serial += 1
            out.append("Applied " + name + ": serial " + str(serial))
        else:
            if event[1] > 0:
                serial += 1
            out.append("Applied directly: serial " + str(serial))
    return out

tf-detect-drift.solution:
def classifyDrift(config, state, actual, ignore_changes):
    rows = []
    for address in sorted(state):
        if address not in actual:
            rows.append([address, "", "deleted"])
            continue
        ignored = ignore_changes.get(address, [])
        ignore_all = "all" in ignored
        for attr in sorted(state[address]):
            s = state[address][attr]
            a = actual[address][attr]
            c = config[address][attr]
            skip = ignore_all or attr in ignored
            if a == s:
                if c != s and not skip:
                    rows.append([address, attr, "pending"])
            elif skip:
                rows.append([address, attr, "drift-ignored"])
            elif c == a:
                rows.append([address, attr, "drift-adopted"])
            elif c == s:
                rows.append([address, attr, "drift-revert"])
            else:
                rows.append([address, attr, "drift-overwrite"])
    return rows

tf-version-constraint.solution:
def satisfies(version, constraint):
    def numbers(text):
        return [int(part) for part in text.strip().split(".")]

    def padded(nums):
        return tuple(nums + [0] * (3 - len(nums)))

    v = padded(numbers(version))
    for term in constraint.split(","):
        term = term.strip()
        operator = "="
        for candidate in ("~>", ">=", "<=", "!=", ">", "<", "="):
            if term.startswith(candidate):
                operator = candidate
                term = term[len(candidate):]
                break
        written = numbers(term)
        c = padded(written)
        if operator == "=":
            ok = v == c
        elif operator == "!=":
            ok = v != c
        elif operator == ">":
            ok = v > c
        elif operator == ">=":
            ok = v >= c
        elif operator == "<":
            ok = v < c
        elif operator == "<=":
            ok = v <= c
        else:
            if len(written) == 2:
                ceiling = (written[0] + 1, 0, 0)
            else:
                ceiling = (written[0], written[1] + 1, 0)
            ok = c <= v < ceiling
        if not ok:
            return False
    return True

tf-version-select.solution:
def selectProvider(available, constraints, locked, upgrade):
    def numbers(text):
        return [int(part) for part in text.strip().split(".")]

    def padded(nums):
        return tuple(nums + [0] * (3 - len(nums)))

    def term_ok(v, term):
        term = term.strip()
        operator = "="
        for candidate in ("~>", ">=", "<=", "!=", ">", "<", "="):
            if term.startswith(candidate):
                operator = candidate
                term = term[len(candidate):]
                break
        written = numbers(term)
        c = padded(written)
        if operator == "=":
            return v == c
        if operator == "!=":
            return v != c
        if operator == ">":
            return v > c
        if operator == ">=":
            return v >= c
        if operator == "<":
            return v < c
        if operator == "<=":
            return v <= c
        if len(written) == 2:
            ceiling = (written[0] + 1, 0, 0)
        else:
            ceiling = (written[0], written[1] + 1, 0)
        return c <= v < ceiling

    def allowed(version):
        v = padded(numbers(version))
        return all(term_ok(v, term) for constraint in constraints for term in constraint.split(","))

    if locked is not None and not upgrade:
        if allowed(locked):
            return locked
        return "Error: locked version " + locked + " does not match constraints"

    candidates = [version for version in available if allowed(version)]
    if not candidates:
        return "Error: no available version matches"
    return max(candidates, key=lambda version: padded(numbers(version)))
